/** Natural proportions of each piece, so callers size by height alone. */
const MARK_RATIO = 62.0 / 86.0;
const WORD_VB = "0.20 -75.00 550.90 79.40";
const WORD_RATIO = 550.9 / 79.4;
const LOCK_VB = "-2 -99.00 664.05 126.00";
const LOCK_RATIO = 664.05 / 126.00;

interface Props {
  /** Height in px. Width follows the artwork. */
  height?: number;
  className?: string;
}

/** The stub on its own: favicons, app icons, the corner of a ticket. */
export function LogoMark({ height = 28, className }: Props) {
  return (
    <svg
      viewBox="0 0 62.0 86.0"
      height={height}
      width={height * MARK_RATIO}
      className={className}
      role="img"
      aria-label="CrowdBuzz"
    >
      <path d={MARK} fillRule="evenodd" fill="var(--logo-mark, var(--coral, #FF6A45))" />
    </svg>
  );
}

/** The name on its own, for places that already show the mark. */
export function Wordmark({ height = 20, className }: Props) {
  return (
    <svg
      viewBox={WORD_VB}
      height={height}
      width={height * WORD_RATIO}
      className={className}
      role="img"
      aria-label="CrowdBuzz"
    >
      <path d={WORD} fill="currentColor" />
    </svg>
  );
}

/** The full lockup. This is the one that goes in a nav bar or a footer. */
export function Logo({ height = 26, className }: Props) {
  return (
    <svg
      viewBox={LOCK_VB}
      height={height}
      width={height * LOCK_RATIO}
      className={className}
      role="img"
      aria-label="CrowdBuzz"
    >
      <g transform="translate(0 -97.00) scale(1.41860)">
        <path d={MARK} fillRule="evenodd" fill="var(--logo-mark, var(--coral, #FF6A45))" />
      </g>
      <path d={WORD} transform="translate(111.95 0)" fill="currentColor" />
    </svg>
  );
}
